  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C74"],
      "claim": "Disopyramide, a close structural analogue sharing phenyl, pyridyl, and basic amine features, has an absolute oral bioavailability of roughly 80% in patients, directly supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Meperidine, a basic phenylpiperidine analogue, has about 50% oral bioavailability despite first-pass metabolism, supporting F above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C66"],
      "claim": "Methadone, a lipophilic basic amine with diphenyl character, has an average oral bioavailability of about 80%, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Vismodegib, despite saturable absorption and a more complex polar structure, has an absolute bioavailability of 31.8% in humans, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C54"],
      "claim": "Atazanavir, a larger basic drug with pyridyl and aromatic groups, has an oral bioavailability of 60-68%, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Pritelivir, a heteroaromatic sulfonamide with a pyridyl substituent, shows 75% oral bioavailability after a single dose, supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All transferable experimental evidence from structurally related basic amines and heteroaromatic drugs with phenyl/pyridyl motifs shows oral bioavailability well above 20%, mostly 30-90%. The query's full ionization at pH 7.4 is not disqualifying because several close analogues with similar basicity also have high F.",
  "evidence_gaps": [
    "No direct experimental bioavailability data exist for the exact query molecule.",
    "No specific data on first-pass metabolism, efflux transport, or formulation effects for the query.",
    "The physicochemical prior is mixed due to full ionization at physiological pH, but this is outweighed by consistent experimental evidence from close analogues."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

